{
  "format": "toolroll-flow",
  "version": 1,
  "name": "template triage",
  "about": "Sort new issues → Fix it → Review the fix → Close the issue → Sort by hand → Answer it → Write the reply → Check the reply → Reply on the issue → Feature ideas → Done",
  "needs": [
    "github",
    "openrouter"
  ],
  "parameters": [],
  "zones": [
    {
      "id": "sort",
      "title": "Sort new issues",
      "kind": "sort",
      "question": "What kind of request is this?",
      "answers": [
        {
          "answer": "Bug",
          "means": "Something is broken, crashes or behaves wrongly",
          "goesTo": "fix"
        },
        {
          "answer": "Feature",
          "means": "A request for something new, or to change how something works",
          "goesTo": "ideas"
        },
        {
          "answer": "Question",
          "means": "Someone asking how to do something, or asking for help",
          "goesTo": "answer"
        },
        {
          "answer": "Something else",
          "means": "Anything that isn't a bug, a feature request or a question",
          "goesTo": "by-hand"
        }
      ],
      "sureAt": 80,
      "alsoNote": [
        {
          "id": "urgency",
          "question": "How urgent is this?",
          "kind": "score",
          "levels": [
            "Routine: no deadline and nothing is blocked",
            "Soon: it hurts, but there's a workaround",
            "Now: something is blocked, broken for many people, or there's a deadline"
          ]
        }
      ],
      "ifNotSure": "by-hand",
      "at": {
        "x": 0,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "fix",
      "title": "Fix it",
      "kind": "task",
      "instructions": "{{card.title}}\n\n{{card.description}}\n\nChanges asked for (if any): {{note}}",
      "planning": "auto",
      "next": "review",
      "at": {
        "x": 420,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "blue"
      }
    },
    {
      "id": "review",
      "title": "Review the fix",
      "kind": "approval",
      "decider": "owner",
      "next": "close",
      "ifFails": "fix",
      "at": {
        "x": 840,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "amber"
      }
    },
    {
      "id": "close",
      "title": "Close the issue",
      "kind": "update",
      "message": "Fixed: {{card.title}}. Thanks for the report!",
      "close": true,
      "next": "done",
      "at": {
        "x": 1260,
        "y": 0,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    },
    {
      "id": "by-hand",
      "title": "Sort by hand",
      "kind": "inbox",
      "at": {
        "x": 0,
        "y": 400,
        "w": 260,
        "h": 300,
        "color": "slate"
      }
    },
    {
      "id": "answer",
      "title": "Answer it",
      "kind": "report",
      "instructions": "Answer this question for the person who asked: clearly, briefly and in plain words, using what is in the repository.\n\nQuestion: {{card.title}}\n{{card.description}}\n\nFeedback to address (if any): {{note}}",
      "next": "write-reply",
      "at": {
        "x": 420,
        "y": 340,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "write-reply",
      "title": "Write the reply",
      "kind": "draft",
      "instructions": "Write a short, friendly reply to the person who asked, answering their question from the research notes. Plain words; say what to do next if anything.",
      "next": "check-answer",
      "at": {
        "x": 840,
        "y": 340,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "check-answer",
      "title": "Check the reply",
      "kind": "approval",
      "decider": "owner",
      "next": "reply",
      "ifFails": "write-reply",
      "at": {
        "x": 1260,
        "y": 340,
        "w": 260,
        "h": 300,
        "color": "amber"
      }
    },
    {
      "id": "reply",
      "title": "Reply on the issue",
      "kind": "update",
      "message": "{{stage.write-reply}}",
      "close": true,
      "next": "done",
      "at": {
        "x": 1680,
        "y": 340,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    },
    {
      "id": "ideas",
      "title": "Feature ideas",
      "kind": "inbox",
      "at": {
        "x": 420,
        "y": 680,
        "w": 260,
        "h": 300,
        "color": "slate"
      }
    },
    {
      "id": "done",
      "title": "Done",
      "kind": "done",
      "at": {
        "x": 2100,
        "y": 170,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    }
  ],
  "triggers": [],
  "scripts": []
}

