{
  "format": "toolroll-flow",
  "version": 1,
  "name": "gallery ui-inspiration",
  "about": "Find examples → Implement, remix or ignore? → Build it → Pull request → Send the result → Done",
  "needs": [
    "github"
  ],
  "parameters": [],
  "zones": [
    {
      "id": "find",
      "title": "Find examples",
      "kind": "report",
      "instructions": "Pick one surface of this project (a screen or a flow) that no recent commit or earlier inspiration covered.\n\nWith Mobbin, read only: find 3 real app examples for it. For each: the pattern, why it fits here, how it plugs into this code (files and components), and a Mobbin screenshot.\n\nFeedback to address (if any): {{note}}",
      "next": "choose",
      "at": {
        "x": 0,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "choose",
      "title": "Implement, remix or ignore?",
      "kind": "choose",
      "options": [
        {
          "label": "Implement",
          "goesTo": "build"
        },
        {
          "label": "Ignore",
          "goesTo": "end"
        }
      ],
      "ifReplied": "build",
      "at": {
        "x": 360,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "amber"
      }
    },
    {
      "id": "build",
      "title": "Build it",
      "kind": "task",
      "instructions": "Build the chosen example from the report into this project with its own components. A note below is a remix: follow it.\n\nThe report:\n{{stage.find}}\n\nChanges asked for (if any): {{note}}",
      "planning": "auto",
      "next": "pull-request",
      "at": {
        "x": 720,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "blue"
      }
    },
    {
      "id": "pull-request",
      "title": "Pull request",
      "kind": "pull-request",
      "next": "send",
      "ifFails": "build",
      "at": {
        "x": 1080,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "blue"
      }
    },
    {
      "id": "send",
      "title": "Send the result",
      "kind": "send",
      "next": "done",
      "at": {
        "x": 1440,
        "y": 0,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    },
    {
      "id": "done",
      "title": "Done",
      "kind": "done",
      "at": {
        "x": 1800,
        "y": 0,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    }
  ],
  "triggers": [],
  "scripts": []
}

