{
  "format": "toolroll-flow",
  "version": 1,
  "name": "gallery worker-errors",
  "about": "Read the errors → Worth fixing? → Find the cause → Fix or ignore? → Fix it → Pull request → Done → Ignored",
  "needs": [
    "github",
    "openrouter"
  ],
  "parameters": [],
  "zones": [
    {
      "id": "read",
      "title": "Read the errors",
      "kind": "report",
      "instructions": "With Cloudflare, read this week's Workers and Pages errors and analytics. Read only. List each error with its count, its Worker or Pages project, and when it started. Say “No errors” if there are none.\n\nFeedback to address (if any): {{note}}",
      "next": "worth-fixing",
      "at": {
        "x": 0,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "worth-fixing",
      "title": "Worth fixing?",
      "kind": "sort",
      "question": "Do these errors come from this project's code, often enough to fix now?",
      "answers": [
        {
          "answer": "Fix it",
          "means": "Errors from our own code that are new, frequent or hurt people",
          "goesTo": "find-cause"
        },
        {
          "answer": "Ignore",
          "means": "No errors, or only noise: bots, a provider's outage, something known",
          "goesTo": "ignored"
        }
      ],
      "sureAt": 80,
      "ifNotSure": "find-cause",
      "at": {
        "x": 360,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "find-cause",
      "title": "Find the cause",
      "kind": "report",
      "instructions": "Errors worth fixing:\n{{stage.read}}\n\nWith Cloudflare, read the worst one's logs. Read only. Find the cause in this code, citing files and lines, and say what change fixes it.\n\nFeedback to address (if any): {{note}}",
      "next": "choose",
      "at": {
        "x": 720,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "violet"
      }
    },
    {
      "id": "choose",
      "title": "Fix or ignore?",
      "kind": "choose",
      "options": [
        {
          "label": "Fix",
          "goesTo": "fix"
        },
        {
          "label": "Ignore",
          "goesTo": "end"
        }
      ],
      "ifReplied": "fix",
      "at": {
        "x": 1080,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "amber"
      }
    },
    {
      "id": "fix",
      "title": "Fix it",
      "kind": "task",
      "instructions": "Fix this error, with a regression check where one fits.\n\nThe report:\n{{stage.find-cause}}\n\nChanges asked for (if any): {{note}}",
      "planning": "auto",
      "next": "pull-request",
      "at": {
        "x": 1440,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "blue"
      }
    },
    {
      "id": "pull-request",
      "title": "Pull request",
      "kind": "pull-request",
      "next": "done",
      "ifFails": "fix",
      "at": {
        "x": 1800,
        "y": 0,
        "w": 260,
        "h": 300,
        "color": "blue"
      }
    },
    {
      "id": "done",
      "title": "Done",
      "kind": "done",
      "at": {
        "x": 2160,
        "y": 0,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    },
    {
      "id": "ignored",
      "title": "Ignored",
      "kind": "done",
      "at": {
        "x": 720,
        "y": 380,
        "w": 260,
        "h": 220,
        "color": "green"
      }
    }
  ],
  "triggers": [],
  "scripts": []
}

